const title = document.getElementById('title');
const btn = document.getElementById('btn');
const list = document.getElementById('list');
const input = document.getElementById('input');

// 直接操作 DOM 更新畫面
btn.addEventListener('click', () => {
  title.textContent = '已點擊！';
  list.innerHTML = '<li>新項目</li>';
  input.value = '';
});`,highlightLines:[2,3,4,5,9,10,11]}]},{id:"multi-access-problem",title:"多處存取的困境",description:"當應用程式變複雜，多個功能需要存取同一份資料時，直接操作 DOM 的方式會變得難以維護。每個功能都需要知道 DOM 結構，修改時容易產生錯誤。",preview:{type:"component",component:NE},codeBlocks:[{language:"javascript",filename:"problem.js",code:`// 功能 A: 更新使用者名稱
