const promise = new Promise((resolve, reject) => {
  // 模擬非同步操作
  setTimeout(() => {
    const success = true;

    if (success) {
      resolve('操作成功！');  // 成功時調用
    } else {
      reject('操作失敗');     // 失敗時調用
    }
  }, 1000);
});

// 使用 Promise
promise
  .then(result => console.log(result))  // 成功
