function fetchData(id) {
  return new Promise((resolve, reject) => {
    setTimeout(() => {
      if (id > 0) {
        resolve({ id, name: '小明' });
      } else {
        reject(new Error('ID 無效'));
      }
    }, 1000);
  });
}

// 2. 使用 async/await 調用
async function getUserData() {
  try {
    console.log('開始獲取資料...');

    const user = await fetchData(1);  // 等待 Promise
    console.log('用戶資料:', user);

    return user;
  } catch (error) {
    console.error('錯誤:', error.message);
  }
}

// 3. 執行
